from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected exactly one match, found {count}")
    return text.replace(old, new, 1)


numeric_path = Path("src/engcalc_colab/numeric.py")
numeric = numeric_path.read_text()

old_partial = '''    def partial_substitutions(\n        self,\n        expression: sp.Expr,\n        allowed_unresolved: set[str],\n    ) -> tuple[dict[str, Any], tuple[str, ...]]:\n        expr = sp.sympify(expression)\n        names = sorted(symbol.name for symbol in expr.free_symbols)\n        missing = [\n            name\n            for name in names\n            if name not in self.values and name not in allowed_unresolved\n        ]\n        if missing:\n            hint = diagnostic_hint("unresolved_numeric_symbols", names=tuple(missing))\n            raise EngEvaluationError(\n                "numeric evaluation requires values for: "\n                + ", ".join(missing)\n                + f". {hint}"\n            )\n\n        substitutions = {\n            name: self.values[name]\n            for name in names\n            if name in self.values\n        }\n        unresolved = tuple(\n            name\n            for name in names\n            if name not in substitutions\n        )\n        return substitutions, unresolved\n'''

new_partial = '''    def partial_substitutions(\n        self,\n        expression: sp.Expr,\n        allowed_unresolved: set[str] | None = None,\n        overrides: dict[str, Any] | None = None,\n    ) -> tuple[dict[str, Any], tuple[str, ...]]:\n        expr = sp.sympify(expression)\n        overrides = dict(overrides or {})\n        names = sorted(symbol.name for symbol in expr.free_symbols)\n        substitutions = {\n            name: overrides[name] if name in overrides else self.values[name]\n            for name in names\n            if name in overrides or name in self.values\n        }\n        unresolved = tuple(\n            name\n            for name in names\n            if name not in substitutions\n        )\n\n        if allowed_unresolved is not None:\n            unexpected = [\n                name\n                for name in unresolved\n                if name not in allowed_unresolved\n            ]\n            if unexpected:\n                hint = diagnostic_hint(\n                    "unresolved_numeric_symbols",\n                    names=tuple(unexpected),\n                )\n                raise EngEvaluationError(\n                    "numeric evaluation requires values for: "\n                    + ", ".join(unexpected)\n                    + f". {hint}"\n                )\n\n        return substitutions, unresolved\n'''

numeric = replace_once(numeric, old_partial, new_partial, "partial_substitutions")

old_poly = '''    def evaluate_partial_polynomial(\n        self,\n        expression: sp.Expr,\n        variable: str,\n    ) -> tuple[tuple[int, Any], ...] | None:\n        """Evaluate known coefficients of a polynomial while leaving its variable free."""\n        expr = sp.sympify(expression)\n        symbol = sp.Symbol(variable)\n        try:\n            polynomial = sp.Poly(expr, symbol)\n        except PolynomialError:\n            return None\n\n        evaluated_terms: list[tuple[int, Any]] = []\n        for (power,), coefficient in reversed(polynomial.terms()):\n            _, quantity = self.evaluate_symbolic(coefficient)\n            evaluated_terms.append((int(power), quantity))\n        return tuple(evaluated_terms)\n'''

new_poly = '''    def evaluate_partial_polynomial(\n        self,\n        expression: sp.Expr,\n        variable: str,\n        overrides: dict[str, Any] | None = None,\n    ) -> tuple[tuple[int, Any], ...] | None:\n        """Evaluate known coefficients of a polynomial while leaving its variable free."""\n        expr = sp.sympify(expression)\n        symbol = sp.Symbol(variable)\n        try:\n            polynomial = sp.Poly(expr, symbol)\n        except PolynomialError:\n            return None\n\n        evaluated_terms: list[tuple[int, Any]] = []\n        for (power,), coefficient in reversed(polynomial.terms()):\n            _, quantity = self.evaluate_symbolic(\n                coefficient,\n                overrides=overrides,\n            )\n            evaluated_terms.append((int(power), quantity))\n        return tuple(evaluated_terms)\n'''

numeric = replace_once(numeric, old_poly, new_poly, "evaluate_partial_polynomial")
numeric_path.write_text(numeric)


engine_path = Path("src/engcalc_colab/engine.py")
engine = engine_path.read_text()

old_resolver = '''    def _resolve_numeric_user_function_argument(self, node: ast.AST):\n        try:\n            return self._resolve_numeric_function_argument(node)\n        except EngEvaluationError as exc:\n            if not (\n                isinstance(node, ast.Call)\n                and isinstance(node.func, ast.Name)\n                and node.func.id in self.engine.functions\n                and "unsupported numeric function" in str(exc)\n            ):\n                raise\n            symbolic = self.visit(node)\n            _, quantity = self.engine.numeric_context.evaluate_symbolic(symbolic)\n            return quantity\n'''

new_resolver = '''    def _resolve_numeric_user_function_argument(self, node: ast.AST):\n        try:\n            return self._resolve_numeric_function_argument(node)\n        except EngEvaluationError as exc:\n            user_function_fallback = (\n                isinstance(node, ast.Call)\n                and isinstance(node.func, ast.Name)\n                and node.func.id in self.engine.functions\n                and "unsupported numeric function" in str(exc)\n            )\n            unresolved_name_fallback = "unknown numeric name" in str(exc)\n            if not (user_function_fallback or unresolved_name_fallback):\n                raise\n\n            symbolic = self.visit(node)\n            try:\n                _, quantity = self.engine.numeric_context.evaluate_symbolic(symbolic)\n            except EngEvaluationError as symbolic_exc:\n                if "numeric evaluation requires values for:" in str(symbolic_exc):\n                    return sp.sympify(symbolic)\n                raise\n            return quantity\n'''

engine = replace_once(engine, old_resolver, new_resolver, "numeric argument fallback")

old_unresolved = '''                unresolved = [\n                    (index, argument_node, argument_value)\n                    for index, (argument_node, argument_value) in enumerate(\n                        zip(argument.args, argument_values)\n                    )\n                    if isinstance(argument_value, sp.Symbol)\n                ]\n                if unresolved:\n                    if len(argument.args) == 1:\n                        _, argument_node, argument_value = unresolved[0]\n                        if isinstance(argument_node, ast.Name):\n                            if target_unit is not None:\n                                raise EngEvaluationError(\n                                    "target-unit conversion requires a fully numeric result"\n                                )\n                            parameter = self.engine.resolve_symbol(function.parameters[0])\n                            bindings = {parameter: argument_value}\n                            if any(\n                                item.func in _INVERSE_TRIG_SYMBOLIC_FUNCTIONS\n                                for item in sp.preorder_traversal(symbolic_expression)\n                            ):\n                                symbolic_expression = _substitute_preserving_inverse_trig(\n                                    symbolic_expression,\n                                    bindings,\n                                )\n                            else:\n                                symbolic_expression = symbolic_expression.xreplace(bindings)\n                            substitutions, unresolved_symbols = (\n                                self.engine.numeric_context.partial_substitutions(\n                                    symbolic_expression,\n                                    allowed_unresolved={argument_node.id},\n                                )\n                            )\n                            evaluated_terms = (\n                                self.engine.numeric_context.evaluate_partial_polynomial(\n                                    symbolic_expression,\n                                    argument_node.id,\n                                )\n                            )\n                            self.partial_numeric_evaluation = (\n                                symbolic_expression,\n                                substitutions,\n                                unresolved_symbols,\n                                evaluated_terms,\n                                display_name,\n                                display_arguments,\n                            )\n                            return symbolic_expression\n\n                    unresolved_names = tuple(\n                        sorted({value.name for _, _, value in unresolved})\n                    )\n                    hint = diagnostic_hint(\n                        "unresolved_numeric_symbols",\n                        names=unresolved_names,\n                    )\n                    raise EngEvaluationError(\n                        "numeric evaluation requires values for: "\n                        + ", ".join(unresolved_names)\n                        + f". {hint}"\n                    )\n\n'''

new_unresolved = '''                unresolved = [\n                    (parameter, argument_expression, argument_value)\n                    for parameter, argument_expression, argument_value in zip(\n                        function.parameters,\n                        argument_expressions,\n                        argument_values,\n                    )\n                    if isinstance(argument_value, sp.Expr)\n                ]\n                if unresolved:\n                    overrides = {}\n                    bindings = {}\n                    for parameter, argument_expression, argument_value in zip(\n                        function.parameters,\n                        argument_expressions,\n                        argument_values,\n                    ):\n                        if isinstance(argument_value, sp.Expr):\n                            bindings[self.engine.resolve_symbol(parameter)] = (\n                                sp.sympify(argument_expression)\n                            )\n                        else:\n                            overrides[parameter] = argument_value\n\n                    if bindings:\n                        symbolic_expression = _substitute_preserving_inverse_trig(\n                            symbolic_expression,\n                            bindings,\n                        )\n\n                    substitutions, unresolved_symbols = (\n                        self.engine.numeric_context.partial_substitutions(\n                            symbolic_expression,\n                            allowed_unresolved=None,\n                            overrides=overrides,\n                        )\n                    )\n\n                    if target_unit is not None:\n                        suffix = (\n                            ": " + ", ".join(unresolved_symbols)\n                            if unresolved_symbols\n                            else ""\n                        )\n                        raise EngEvaluationError(\n                            "target-unit conversion requires a fully numeric result"\n                            + suffix\n                        )\n\n                    evaluated_terms = None\n                    if len(unresolved_symbols) == 1:\n                        evaluated_terms = (\n                            self.engine.numeric_context.evaluate_partial_polynomial(\n                                symbolic_expression,\n                                unresolved_symbols[0],\n                                overrides=overrides,\n                            )\n                        )\n\n                    self.partial_numeric_evaluation = (\n                        symbolic_expression,\n                        substitutions,\n                        unresolved_symbols,\n                        evaluated_terms,\n                        display_name,\n                        display_arguments,\n                    )\n                    return symbolic_expression\n\n'''

engine = replace_once(engine, old_unresolved, new_unresolved, "generalized partial branch")
engine_path.write_text(engine)
